/bin/zsh -lc "ls -la && python - <<'PY'
import json
for f in ['source.json','policy.json','coordination.json']:
 d=json.load(open(f)); print('\\nFILE',f, 'TYPE',type(d).__name__)
 if f=='source.json':
  print('keys',list(d) if isinstance(d,dict) else '')
  a=d if isinstance(d,list) else d.get('articles',d.get('sources',[]))
  print('count',len(a))
  for i,x in enumerate(a): print(i,{k:v for k,v in x.items() if k not in ['source_xml','source_notes_xml']}, 'xml_len',len(x.get('source_xml','')), 'notes_len',len(x.get('source_notes_xml','') or ''))
 else: print(json.dumps(d,ensure_ascii=False,indent=2))
PY"

